const j = $json;
const header = (name) => {
  const hs = j.payload?.headers || j.headers || [];
  const h = Array.isArray(hs) ? hs.find(x => String(x.name).toLowerCase() === name) : null;
  return h?.value || '';
};
const decode = (s='') => {
  try { return Buffer.from(String(s).replace(/-/g,'+').replace(/_/g,'/'), 'base64').toString('utf8'); } catch { return ''; }
};
const walk = (p) => {
  if (!p) return '';
  if (p.mimeType === 'text/plain' && p.body?.data) return decode(p.body.data);
  for (const x of (p.parts || [])) { const v = walk(x); if (v) return v; }
  return '';
};
const body = j.textPlain || j.text || j.body || walk(j.payload) || j.snippet || '';
return { json: {
  gmail_message_id: j.id || j.messageId || '',
  thread_id: j.threadId || '',
  from: j.from?.value?.[0]?.address || j.from || header('from'),
  to: j.to?.value?.[0]?.address || j.to || header('to'),
  subject: j.subject || header('subject'),
  received_at: j.date || header('date'),
  body_text: String(body).slice(0, 30000),
  source_snippet: j.snippet || String(body).slice(0, 500)
} };

