const r = $json;
let text = r.output_text || '';
if (!text && Array.isArray(r.output)) {
  for (const o of r.output) for (const c of (o.content || [])) if (c.text) text += c.text;
}
if (!text) throw new Error('OpenAI returned no text');
let a;
try { a = JSON.parse(text); } catch (e) { throw new Error('OpenAI did not return valid JSON: ' + text.slice(0,300)); }
const profile = $('Configure Candidate Profile').item.json;
return { json: { ...profile, analysis: a, is_job_opening: a.is_job_opening === true, fit_score: Number(a.fit_score || 0), confidence: Number(a.confidence || 0) } };

